import {
  Color,
  DataTexture,
  LinearMipmapLinearFilter,
  LinearFilter,
  RepeatWrapping,
  RGBAFormat,
  SRGBColorSpace,
  UnsignedByteType,
} from 'three';
import type { SubstrateKind } from '../../core/types';
import { Rng } from '../../core/rng';

/**
 * Procedural, tileable substrate detail textures (albedo+height, normal, occlusion/roughness),
 * generated by "pouring" thousands of grains into a periodic height buffer: each grain is an
 * irregular ellipse with its own color, roughness and height profile, z-buffered against the
 * grains already there so they pack and overlap like real sediment. Grain sizes and colors are
 * taken from real aquarium substrates (sizes in mm; colors are wet, sRGB).
 */

type RGB = [number, number, number];

interface Swatch {
  c: RGB;
  /** Relative frequency. */
  w: number;
  /** Roughness override (wet polished pebbles ≈ 0.35, matte soil ≈ 0.9). */
  rough?: number;
}

interface GrainLayer {
  /** Area coverage multiplier (≥1.5 gives a fully packed layer). */
  coverage: number;
  /** Grain radius range (mm). */
  rMin: number;
  rMax: number;
  /** Elongation range (1 = round). */
  aspect: [number, number];
  /** Outline irregularity 0 (smooth ellipse) .. 0.35 (angular, fractured). */
  rough: number;
  /** 'dome' rounded grains, 'facet' angular fragments, 'flake' flat shell bits. */
  profile: 'dome' | 'facet' | 'flake';
  /** Relative dome height (fraction of radius). */
  height: number;
  /** Within-grain albedo noise amplitude. */
  speckle: number;
  /** Per-grain color jitter (fraction). */
  jitter: number;
  palette: Swatch[];
  /** Default roughness for this layer. */
  roughness: number;
}

export interface SubstrateSpec {
  /** Meters covered by one texture tile. */
  tile: number;
  /** Color of the voids between grains (sRGB). */
  voidColor: RGB;
  layers: GrainLayer[];
  /** Large-scale tone variation in the shader: amplitude and tint direction. */
  macroAmp: number;
  macroTint: RGB;
  /** Normal map strength. */
  normalScale: number;
  /** Gentle mid-scale undulation of the surface (fraction of tile). */
  undulation: number;
}

// ---------------------------------------------------------------------------------------------
// Specs per substrate kind
// ---------------------------------------------------------------------------------------------

const sand = (palette: Swatch[], rMin: number, rMax: number, extra: Partial<GrainLayer> = {}): GrainLayer => ({
  coverage: 2.4, rMin, rMax, aspect: [1, 1.5], rough: 0.12, profile: 'dome', height: 0.7, speckle: 0.06, jitter: 0.07,
  palette, roughness: 0.62, ...extra,
});

